def format_number(n: int, html: bool = False) -> str:
    raw = f'{n:,}'
    if html:
        return raw.replace(',', '<span class="num-gap"></span>')
    return raw.replace(',', '\u200a')


def compute_date_segments(
    api: list[ApiEntry],
) -> list[tuple[datetime.date, datetime.date, str, int]]:
    by_date: dict[datetime.date, ApiEntry] = {}
    for entry in api:
        if entry.date not in by_date or (not by_date[entry.date].url and entry.url):
            by_date[entry.date] = entry

    sorted_dates = sorted(by_date.keys())
    if not sorted_dates:
        return []

    segments: list[tuple[datetime.date, datetime.date, str, int]] = []
    seg_start = sorted_dates[0]
    seg_kind = 'image' if by_date[seg_start].url and by_date[seg_start].url.strip() else 'no_image'
    prev_d = seg_start
    seg_count = 1

    for d in sorted_dates[1:]:
        kind = 'image' if by_date[d].url and by_date[d].url.strip() else 'no_image'
        if (d - prev_d).days == 1 and kind == seg_kind:
            prev_d = d
            seg_count += 1
        else:
            segments.append((seg_start, prev_d, seg_kind, seg_count))
            seg_start = d
            seg_kind = kind
            prev_d = d
            seg_count = 1

    segments.append((seg_start, prev_d, seg_kind, seg_count))
    return segments


def build_status_template_context(
    region_to_api: dict[str, list[ApiEntry]],
    today: datetime.date | None = None,
) -> dict[str, object]:
    if today is None:
        today = datetime.date.today()

    all_dates: list[datetime.date] = []
    for api in region_to_api.values():
        for entry in api:
            all_dates.append(entry.date)

    if not all_dates:
        global_min = today
        global_max = today
    else:
        global_min = min(all_dates)
        global_max = max(today, max(all_dates))

    total_days = max(1, (global_max - global_min).days + 1)
    total_images = sum(len(api) for api in region_to_api.values())
    total_regions = len(region_to_api)
    span_years = str(int(total_days // 365.25))

    all_region_ids: list[str] = []
    for rid in REGION_METADATA:
        if rid in region_to_api:
            all_region_ids.append(rid)
    for rid in sorted(region_to_api.keys()):
        if rid not in all_region_ids:
            all_region_ids.append(rid)

    total_gigabytes: int | None = None
    try:
        storage = CloudflareR2()
        usage = storage.get_bucket_usage()
        if usage is not None:
            total_gigabytes = int(usage[0] // (1024 ** 3))
    except Exception as e:
        print(f'Warning: Could not fetch R2 bucket usage: {e}')

    ticks: list[dict[str, float | str]] = []
    current_year = global_min.year
    while current_year <= global_max.year:
        tick_date = datetime.date(current_year, 1, 1)
        if tick_date >= global_min:
            offset = (tick_date - global_min).days
            pct = round(max(0.0, min(100.0, (offset / total_days) * 100.0)), 2)
            ticks.append({'pct': pct, 'label': str(current_year)})
        current_year += 1

    ticks.append({'pct': 100, 'label': 'Now'})

    region_records: list[dict[str, object]] = []
    for rid in all_region_ids:
        api = region_to_api[rid]
        meta = REGION_METADATA.get(rid, {'name': rid, 'lang': '', 'flag': '🌐'})
        flag = meta.get('flag', '🌐')
        name = meta.get('name', rid)
        lang = meta.get('lang', '')
        full_name = f'{name} ({lang})' if lang else name

        raw_segments = compute_date_segments(api)
        images_count = sum(1 for e in api if e.url and e.url.strip())
        total_items = len(api)

        if api:
            api_dates = [e.date for e in api]
            d_min = min(api_dates).strftime('%Y-%m-%d')
            d_max = max(api_dates).strftime('%Y-%m-%d')
            date_range_str = f'{d_min} – {d_max}'
        else:
            date_range_str = 'No data'

        formatted_segments: list[dict[str, int | str]] = []
        for seg_start, seg_end, seg_kind, count in raw_segments:
            x = (seg_start - global_min).days
            w = (seg_end - seg_start).days + 1
            if seg_kind == 'image':
                label = (
                    f'{seg_start.strftime("%Y-%m-%d")} to {seg_end.strftime("%Y-%m-%d")} '
                    f'· {format_number(count)} images'
                )
            else:
                label = (
                    f'{seg_start.strftime("%Y-%m-%d")} to {seg_end.strftime("%Y-%m-%d")} '
                    f'· {format_number(count)} metadata only (no image)'
                )
            formatted_segments.append({'kind': seg_kind, 'x': x, 'w': w, 'label': label})

        region_records.append({
            'id': rid,
            'flag': flag,
            'full_name': full_name,
            'images_count': images_count,
            'total_items': total_items,
            'has_missing_images': images_count < total_items,
            'images_count_formatted': format_number(images_count, html=True),
            'total_items_formatted': format_number(total_items, html=True),
            'date_range_str': date_range_str,
            'segments': formatted_segments,
        })

    return {
        'total_days': total_days,
        'total_images': format_number(total_images, html=True),
        'total_gigabytes': total_gigabytes,
        'span_years': span_years,
        'total_regions': total_regions,
        'ticks': ticks,
        'regions': region_records,
    }


def generate_status_page(
    region_to_api: dict[str, list[ApiEntry]],
    website_root: str | None = None,
) -> None:
    root = website_root or PATH.WEBSITE_ROOT

    template_candidates = [
        mkpath(root, 'status.html'),
        mkpath(PATH.WEBSITE, 'src', 'status.html'),
    ]

    template_path = None
    for candidate in template_candidates:
        if os.path.isfile(candidate):
            template_path = candidate
            break

    if template_path is None:
        raise FileNotFoundError(f'Could not find status.html template in {template_candidates}')

    with open(template_path, 'r', encoding='utf-8') as f:
        template_html = f.read()

    context = build_status_template_context(region_to_api)
    template = Environment(autoescape=False, trim_blocks=True, lstrip_blocks=True).from_string(template_html)
    final_html = template.render(**context)

    status_html_path = mkpath(root, 'status.html')
    with open(status_html_path, 'w', encoding='utf-8') as f:
        f.write(final_html)

    status_dir = mkpath(root, 'status')
    os.makedirs(status_dir, exist_ok=True)
    shutil.copyfile(status_html_path, mkpath(status_dir, 'index.html'))
